INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório tardio (meses ou anos) de uma cirurgia abdominal, o paciente desenvolve abaulamento redutível sobre a cicatriz operatória, que aumenta com a manobra de Valsalva. Qual o diagnóstico?", "options": {"a": "Hérnia Incisional.", "b": "Hérnia Femoral.", "c": "Seroma crônico.", "d": "Abscesso de parede.", "e": "Hematoma tardio."}, "answer": "a", "rationale": "A hérnia incisional é uma falha na cicatrização da aponeurose, comum após laparotomias, especialmente se houve infecção ou esforço precoce.", "option_rationales": {"a": "Correta. Definição de complicação tardia da parede abdominal.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Hérnia Incisional", "Parede Abdominal"]}', 311, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A complicação de estoma conhecida como ''Prolapso'' caracteriza-se por:", "options": {"a": "Afundamento da alça para dentro da cavidade abdominal.", "b": "Saída excessiva da alça intestinal através do orifício do estoma, tornando-se redundante externamente.", "c": "Coloração escura da mucosa.", "d": "Saída de pus ao redor do estoma.", "e": "Obstrução completa do estoma."}, "answer": "b", "rationale": "O prolapso ocorre frequentemente por orifício aponeurótico excessivamente largo ou fixação inadequada da alça.", "option_rationales": {"a": "Incorreta. Isso é retração.", "b": "Correta. Definição morfológica da complicação.", "c": "Incorreta. Isso sugere isquemia/necrose.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Estomas", "Prolapso"]}', 312, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a mastectomia radical com esvaziamento axilar apresenta, no pós-operatório tardio, edema persistente e endurecido do membro superior ipsilateral. Qual o nome desta complicação crônica?", "options": {"a": "Trombose Venosa Profunda.", "b": "Linfedema.", "c": "Flebite superficial.", "d": "Miosite.", "e": "Erisipela bolhosa."}, "answer": "b", "rationale": "O linfedema decorre da interrupção das vias de drenagem linfática da axila, sendo uma complicação frequente e de difícil tratamento em oncologia mamária.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação linfática clássica pós-esvaziamento.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Mastologia", "Pós-operatório", "Linfedema", "Complicações"]}', 313, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cirurgia oncológica com linfadenectomia retroperitoneal, observa-se formação de coleção cística clara e indolor próxima aos grandes vasos. Qual o diagnóstico provável?", "options": {"a": "Abscesso fungico.", "b": "Linfocele.", "c": "Hematoma pulsátil.", "d": "Urinoma.", "e": "Metástase imediata."}, "answer": "b", "rationale": "A linfocele é um acúmulo de linfa após dissecção linfática regional, comum em cirurgias de próstata ou ginecológicas oncológicas.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Coleção linfática circunscrita.", "c": "Incorreta.", "d": "Incorreta. Urinoma seria urina.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Urologia", "Pós-operatório", "Linfocele", "Linfáticos"]}', 314, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal medida para prevenir a ocorrência de ''pneumonia associada à ventilação'' (PAV) em pacientes cirúrgicos em UTI?", "options": {"a": "Manter o paciente em decúbito horizontal (0 grau).", "b": "Elevação da cabeceira entre 30 a 45 graus, higiene oral com clorexidina e aspiração de secreções subglóticas.", "c": "Uso profilático de antibióticos de largo espectro para todos.", "d": "Troca diária do circuito do ventilador.", "e": "Uso de apenas sedação profunda contínua."}, "answer": "b", "rationale": "O ''bundle'' de prevenção de PAV foca na redução da microaspiração de secreções orofaríngeas contaminadas.", "option_rationales": {"a": "Incorreta. Favorece a aspiração.", "b": "Correta. Medidas padrão de segurança em terapia intensiva.", "c": "Incorreta. Aumenta resistência bacteriana.", "d": "Incorreta. Aumenta o risco de contaminação do sistema.", "e": "Incorreta. Sedação contínua dificulta o desmame e aumenta risco de PAV."}, "difficulty": "facil", "tags": ["Terapia Intensiva", "Pós-operatório", "PAV", "Prevenção"]}', 315, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A complicação conhecida como ''Evisceração'' pós-operatória precoce (geralmente nos primeiros 7-10 dias) constitui uma emergência cirúrgica que exige:", "options": {"a": "Apenas curativo compressivo seco.", "b": "Proteção das alças intestinais expostas com compressas úmidas em soro fisiológico estéril e retorno imediato ao centro cirúrgico para fechamento da parede.", "c": "Uso de pomada antibiótica local no intestino.", "d": "Tentar empurrar as alças para dentro no leito sem anestesia.", "e": "Iniciar dieta sólida para o intestino descer sozinho."}, "answer": "b", "rationale": "O conteúdo abdominal está exposto e corre risco de dessecação, isquemia e infecção maciça. O fechamento cirúrgico de urgência é obrigatório.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Manejo imediato de deiscência total de parede.", "c": "Incorreta.", "d": "Incorreta. Risco de lesão intestinal e dor extrema.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Evisceração", "Emergência"]}', 316, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma tireoidectomia total, o paciente apresenta rouquidão persistente e soprosa. Ao realizar laringoscopia, observa-se uma prega vocal paralisada em posição paramediana. Qual o nervo lesionado?", "options": {"a": "Nervo Laríngeo Superior.", "b": "Nervo Laríngeo Recorrente (unilateral).", "c": "Nervo Vago tronco principal.", "d": "Nervo Hipoglosso.", "e": "Nervo Frênico."}, "answer": "b", "rationale": "A lesão do nervo laríngeo recorrente causa paralisia da musculatura intrínseca da laringe (exceto cricotireoideo), resultando em rouquidão.", "option_rationales": {"a": "Incorreta. Causaria perda de tons agudos e cansaço vocal.", "b": "Correta. Lesão iatrogênica clássica em cirurgia de tireoide.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia de Cabeça e Pescoço", "Pós-operatório", "Nervo Recorrente", "Rouquidão"]}', 317, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a complicação mais grave e de urgência respiratória imediata da lesão BILATERAL dos nervos laríngeos recorrentes após uma tireoidectomia?", "options": {"a": "Rouquidão leve apenas.", "b": "Obstrução respiratória alta aguda por paralisia das pregas vocais em adução (fechadas), exigindo frequentemente traqueostomia ou re-intubação.", "c": "Aumentar a salivação.", "d": "Perda de paladar.", "e": "Soluços."}, "answer": "b", "rationale": "Diferente da lesão unilateral, a bilateral impede a abertura da glote para a respiração, constituindo uma emergência de via aérea.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Emergência técnica em cirurgia de cabeça e pescoço.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia de Cabeça e Pescoço", "Pós-operatório", "Vias Aéreas", "Emergência"]}', 318, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia abdominal prolongada apresenta no 10º DPO um quadro de dor abdominal tipo cólica, vômitos biliosos e ausência de eliminação de gases. O Raio-x mostra níveis hidroaéreos e distensão de alças do delgado. Qual o nome desta complicação mecânica?", "options": {"a": "Íleo paralítico persistente.", "b": "Obstrução Intestinal por Brida (aderência) precoce.", "c": "Infecção urinária.", "d": "Pneumonia basal.", "e": "Dumping."}, "answer": "b", "rationale": "A formação de aderências começa logo após a cirurgia. Se uma alça ficar presa ou torcida, ocorre obstrução mecânica, que se diferencia do íleo funcional pela presença de ruídos hidroaéreos aumentados (metálicos) e luta.", "option_rationales": {"a": "Incorreta. No íleo não há luta nem níveis tão francos.", "b": "Correta. Complicação mecânica pós-operatória comum.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Obstrução", "Brida"]}', 319, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A complicação infecciosa conhecida como ''Sinus Tract'' ou Trajeto Sinusal na ferida operatória diferencia-se de uma fístula por:", "options": {"a": "Ser muito mais profunda.", "b": "Comunicar apenas o tecido subcutâneo com a pele, sem conexão com vísceras ocas ou cavidades internas.", "c": "Comunicar dois órgãos entre si.", "d": "Sempre sair fezes.", "e": "Ser causada por vírus."}, "answer": "b", "rationale": "O sinus é um trajeto em fundo cego (geralmente por infecção de corpo estranho como fio de sutura), enquanto a fístula comunica duas superfícies epitelizadas (órgão-óleo/órgão-pele).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Diferencial anatômico importante.", "c": "Incorreta. Isso é fístula interna.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Sinus", "Fístula"]}', 320, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A ocorrência de ''retração'' de um estoma (quando o estoma fica abaixo do nível da pele) dificulta o cuidado e pode levar a qual complicação cutânea secundária?", "options": {"a": "Câncer de pele.", "b": "Dermatite amoniacal/química e lesão de pele periestomal pelo contato direto de efluentes (fezes/urina) com a pele sem proteção da bolsa.", "c": "Aumentar o crescimento de pelos.", "d": "Melhora da cicatrização.", "e": "Flebite gástrica."}, "answer": "b", "rationale": "O estoma deve ser protuso (efeito chafariz) para que o conteúdo caia dentro da bolsa; na retração, o conteúdo infiltra sob a placa protetora, erodindo a pele.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Consequência clínica da falha técnica do estoma.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Estomaterapia", "Pós-operatório", "Estomas", "Dermatite"]}', 321, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a conduta imediata diante de um ''estoma necrótico'' (coloração preta ou cinza-azulada) identificado nas primeiras 24 horas após a cirurgia?", "options": {"a": "Observar por 7 dias para ver se melhora.", "b": "Avaliar a profundidade da necrose (se acima ou abaixo da aponeurose) e, se houver necrose profunda, realizar reoperação urgente para revisão do suprimento sanguíneo e novo estoma.", "c": "Passar apenas pomada de corticoides.", "d": "Colocar gelo no estoma.", "e": "Dar antibióticos venosos apenas."}, "answer": "b", "rationale": "A necrose indica isquemia arterial ou venosa severa. Se a necrose progredir para baixo da fascia, haverá perfuração intraperitoneal e peritonite fecal.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Manejo de emergência de isquemia de alça.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Estoma", "Necrose"]}', 322, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cirurgia de grande porte em paciente de alto risco, qual o sinal clínico MAIS sensível e precoce de insuficiência cardíaca por sobrecarga hídrica (edema agudo de pulmão nascente)?", "options": {"a": "Icterícia.", "b": "Início de estertores crepitantes nas bases pulmonares e surgimento de Terceira Bulha (B3) à ausculta cardíaca.", "c": "Dor na perna.", "d": "Diminuição das plaquetas.", "e": "Aumento do apetite."}, "answer": "b", "rationale": "A B3 é um sinal de disfunção ventricular e sobrecarga de volume, ocorrendo antes mesmo de grandes alterações radiológicas.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Semiologia cardiovascular no pós-operatório.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Pós-operatório", "Insuficiência Cardíaca", "Sinais"]}', 323, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A complicação conhecida como ''Hernia de Parastomal'' é comum após colostomias definitivas. Qual a principal recomendação para sua prevenção técnica?", "options": {"a": "Não fechar a aponeurose.", "b": "Criação do estoma através do músculo reto abdominal e uso criterioso de telas profiláticas em pacientes de alto risco.", "c": "Não usar fios de sutura.", "d": "Fazer o estoma na linha média.", "e": "Não há prevenção."}, "answer": "b", "rationale": "O músculo reto oferece suporte estrutural extra. Estomas fora do músculo tendem a herniar com muito mais facilidade.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Técnica cirúrgica de prevenção de herniações.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Estomas", "Hérnia Parastomal"]}', 324, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia abdominal apresenta, no 5º DPO, drenagem abundante de líquido citrino-rosado (serossanguinolento) em ''água de carne'' que ensopa o curativo. Este sinal (Sinal do Curativo de Miller) é patognomônico de qual complicação?", "options": {"a": "Infecção urinária.", "b": "Deiscência Aponeurótica Incipiente (iminência de evisceração).", "c": "Cura normal da ferida.", "d": "Hemorragia ativa severa.", "e": "Flebite superficial."}, "answer": "b", "rationale": "O líquido é o fluido peritoneal que vaza através de uma pequena abertura na aponeurose já rompida sob a pele ainda íntegra.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Sinal clássico semiológico de deiscência profunda.", "c": "Incorreta.", "d": "Incorreta. Na hemorragia o líquido seria sangue vivo.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Deiscência", "Sinal"]}', 325, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A complicação tardia conhecida como ''Gossypiboma'' (ou Textiloma) refere-se a:", "options": {"a": "Câncer inflamatório de pele.", "b": "Corpo estranho esquecido na cavidade (geralmente compressa de gaze) que causa reação granulomatosa ou abscesso tardio.", "c": "Cicatriz hipertrófica gigante.", "d": "Infeccção por fungos raros.", "e": "Fístula na uretra."}, "answer": "b", "rationale": "É um erro médico grave. A compressa pode causar aderências, fístulas ou erosão para dentro de vísceras.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Epônimo para compressas esquecidas.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Erro Médico", "Corpo Estranho"]}', 326, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual o achado radiológico típico de um ''Gossypiboma'' (compressa esquecida) no abdome quando se utiliza o Raio-x simples pós-operatorio?", "options": {"a": "Nada é visto.", "b": "Presença de uma linha ou imagem radiopaca característica (marcador metálico presente em compressas cirúrgicas padrão).", "c": "Aumento do fígado.", "d": "Derrame pleural.", "e": "Gas no estômago."}, "answer": "b", "rationale": "Compressas cirúrgicas modernas possuem uma fita radiopaca justamente para facilitar a detecção em caso de extravio no centro cirúrgico.", "option_rationales": {"a": "Incorreta. Veria-se a fita radiopaca.", "b": "Correta. Exame de imagem na suspeita de corpo estranho retido.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Segurança", "Imagem"]}', 327, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A complicação conhecida como ''Sinus Pilonidal'' recorrente após cirurgia de ressecção definitiva costuma ocorrer por qual motivo principal?", "options": {"a": "Falta de antibiótico.", "b": "Presença de pelos residuais no sulco interglúteo, má higiene local ou remoção incompleta dos trajetos fistulosos.", "c": "Uso de gelo.", "d": "Alergia ao sabonete.", "e": "Caminhar demais."}, "answer": "b", "rationale": "A base do tratamento é a remoção completa da doença e o controle rigoroso da presença de pelos (atrito e penetração folicular).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Fatores de recorrência cirúrgica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Proctológica", "Pós-operatório", "Cisto Pilonidal", "Recorrência"]}', 328, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma apendicectomia complicada por peritonite, surge uma massa granulomatosa endurecida no flanco direito, com múltiplos trajetos fístulosos que drenam grânulos amarelados (''grânulos de enxofre''). Qual a principal suspeita etiológica?", "options": {"a": "Tuberculose abdominal.", "b": "Actinomicose abdominal (Actinomyces israelii).", "c": "Linfoma de Hodgkin.", "d": "Auscência de cicatrização.", "e": "Flebite gástrica."}, "answer": "b", "rationale": "A actinomicose é uma infecção bacteriana supurativa crônica que pode se manifestar após cirurgias do apêndice, caracterizada pelos trajetos fistulosos e grânulos amarelados típicos.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Infecção cirúrgica específica rara.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Infectologia", "Pós-operatório", "Actinomicose", "Fístula"]}', 329, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A complicação dermatológica conhecida como ''Pioderma Gangrenoso'' pode ocorrer ao redor de estomas (periestomal) em pacientes com qual doença de base concomitante?", "options": {"a": "Hipertensão arterial.", "b": "Doença Inflamatória Intestinal (Retocolite Ulcerativa ou Doença de Crohn).", "c": "Osteoartrite.", "d": "Câncer de tireoide.", "e": "Asma."}, "answer": "b", "rationale": "O pioderma gangrenoso é uma manifestação extraintestinal da DII. No estoma, aparece como úlceras dolorosas, violáceas e de rápida progressão.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Associação clínica sistêmica importante.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Gastroenterologia", "Pós-operatório", "Pioderma", "DII"]}', 330, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em pacientes com fístulas enterocutâneas de ALTO DÉBITO (> 500 ml/dia), qual a principal preocupação imediata no manejo clínico?", "options": {"a": "Melhora da estética da pele.", "b": "Desequilíbrio hidroeletrolítico severo (desidratação e perda de eletrólitos) e desnutrição rápida.", "c": "Excesso de ferro no sangue.", "d": "Auscência de dor.", "e": "Aumento do peso."}, "answer": "b", "rationale": "O corpo perde grandes quantidades de fluido rico em sódio, potássio e bicarbonato, exigindo reposição venosa agressiva e reposicão nutricional parenterica.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Prioridade fisiopatológica no manejo de fístulas.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Fístula", "Alto Débito"]}', 331, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "O uso de ''Octreotide'' (análogo da somatostatina) no manejo de fístulas digestivas de alto débito tem como objetivo principal:", "options": {"a": "Aumentar a salivação.", "b": "Reduzir o volume das secreções gastrointestinais e pancreáticas, facilitando o manejo do paciente e potencialmente o fechamento da fístula.", "c": "Tratar a infecção urinária.", "d": "Melhorar a visão.", "e": "Drenar pus."}, "answer": "b", "rationale": "A somatostatina inibe a maioria das secreções digestivas. Ao reduzir o fluxo através do trajeto fístular, cria-se um ambiente mais favorável à cicatrização.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Papel farmacológico no suporte de fístulas.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Fístula", "Octreotide"]}', 332, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual complicação aguda de ferida operatória se caracteriza pela migração do intestino por dentro da cavidade abdominal através de uma deiscência da aponeurose, mas permanecendo RETIDO sob a pele já devidamente suturada?", "options": {"a": "Evisceração.", "b": "Eventração aguda (Hérnia incisional aguda).", "c": "Flebite gástrica.", "d": "Seroma infeccioso.", "e": "Colite isquêmica."}, "answer": "b", "rationale": "A eventração aguda é a deiscência do plano aponeurótico com a pele mantida fechada. O risco é a pele romper tardiamente e ocorrer evisceração súbita (Saco herniário se formando).", "option_rationales": {"a": "Incorreta. Na evisceração as alças saem da pele.", "b": "Correta. Distinção técnica importante na semiologia cirúrgica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Eventracaão", "Deiscência"]}', 333, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cirurgia de hérnia de disco cervical (acesso anterior), o paciente apresenta dor de garganta intensa, rouquidão e disfagia. A tomografia mostra ar na região pré-vertebral e pescoço. Qual a complicação temida?", "options": {"a": "Faringite viral.", "b": "Perfuração esofágica iatrogênica acidental durante o afastamento das vísceras cervicais.", "c": "Cura rápida.", "d": "Derrame pleural.", "e": "Hérnia de hiato."}, "answer": "b", "rationale": "A perfuração do esôfago é uma emergência pois leva rapidamente a mediastinite supurativa, exigindo controle imediato e drenagem.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Risco técnico específico de acessos cervicais anteriores.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Neurocirurgia", "Pós-operatório", "Esôfago", "Perfuração"]}', 334, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A principal causa de ''osteomielite crônica'' após cirurgias ortopédicas em que houve uso de material de síntese (placas/hastes) é:", "options": {"a": "Excesso de cálcio na dieta.", "b": "Persistência de tecido ósseo necrótico (sequestro ósseo) e biofilme bacteriano no implante que impede a ação dos antibióticos.", "c": "Caminhar rápido demais.", "d": "Auscência de exercícios.", "e": "Falta de vitaminas."}, "answer": "b", "rationale": "O biofilme é uma matriz que protege as bactérias da imunidade e dos antibióticos, exigindo frequentemente a remoção do implante para cura definitiva.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Fisiopatologia da infecção ortopédica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Ortopedia", "Pós-operatório", "Osteomielite", "Implantes"]}', 335, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia abdominal desenvolve quadro de agitação, alucinações visuais, taquicardia e tremores 48-72 horas após a internação. Ele tem história de etilismo pesado. Qual o diagnóstico?", "options": {"a": "Choque Séptico.", "b": "Delirium Tremens (Síndrome de Abstinência Alcoólica grave).", "c": "Pneumonia aguda.", "d": "Encefalite viral.", "e": "Hipotensão reflexa."}, "answer": "b", "rationale": "O estresse cirúrgico e a cessação súbita da ingestão de álcool precipitam a abstinência, que no nível de Delirium Tremens tem alta mortalidade.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação neurológica por abstinência em cirurgia.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Psiquiatria", "Pós-operatório", "Abstinência", "Delirium Tremens"]}', 336, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a medida de prevenção MAIS eficaz para evitar a recidiva de uma hérnia inguinal após o tratamento cirúrgico (herniorrafia)?", "options": {"a": "Não usar fios de sutura.", "b": "Uso de tela (prótese de polipropileno) para reforço do assoalho inguinal sem tensão (Técnica de Lichtenstein).", "c": "Repouso absoluto pelo resto da vida.", "d": "Uso de antibióticos por 1 ano.", "e": "Caminhar apenas na ponta dos pés."}, "answer": "b", "rationale": "O uso de tela revolucionou a cirurgia de hérnia, reduzindo as taxas de recidiva de > 10% para < 1-2%.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Padrão-ouro técnico preventivo.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Herniorrafia", "Recidiva"]}', 337, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório imediato de uma cirurgia de carótida (Endarterectomia), observa-se abaulamento cervical progressivo e desvio de traqueia, com estridor respiratório (ruído ao respirar). Qual a conduta IMEDIATA?", "options": {"a": "Apenas colocar gelo no pescoço e observar.", "b": "Abertura imediata da ferida e evacuação do hematoma compressivo (mesmo no leito se houver asfixia), seguida de retorno ao centro cirúrgico.", "c": "Realizar traqueostomia eletiva amanhã.", "d": "Pedir tomografia urgente.", "e": "Administrar calmantes."}, "answer": "b", "rationale": "Um hematoma no pescoço pode causar compressão venosa e traqueal súbita, levando a asfixia em minutos. A descompressão é prioritária à intubação muitas vezes dificultada pelo edema.", "option_rationales": {"a": "Incorreta. O hematoma pode matar por asfixia.", "b": "Correta. Emergência vascular/via aérea de pescoço.", "c": "Incorreta.", "d": "Incorreta. O tempo para o exame seria fatal.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Vascular", "Pós-operatório", "Hematoma", "Asfixia"]}', 338, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A complicação conhecida como ''Pneumoperitônio Pós-Operatório'' (presença de ar livre na cavidade abdominal no Raio-x) é considerada normal e esperada por até quanto tempo após uma laparotomia aberta?", "options": {"a": "Apenas 1 hora.", "b": "Pode persistir por 3 a 7 dias, devendo ser avaliada em conjunto com o quadro clínico para descartar perfuração víscera.", "c": "Até 30 dias.", "d": "Nunca é normal após a cirurgia.", "e": "Deve durar apenas segundos."}, "answer": "b", "rationale": "O ar entra na cavidade durante a abertura abdominal e demora a ser absorvido pelo peritônio.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Conhecimento de radiologia cirúrgica pós-op.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Radiologia", "Pneumoperitônio"]}', 339, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A principal causa de ''paralisia do nervo radial'' por posicionamento cirúrgico é:", "options": {"a": "Ficar sentado demais.", "b": "Pressão direta sobre a face póstero-lateral do úmero (por exemplo, braço preso em suporte de anestesia mal acolchoado ou paciente deitado sobre o braço).", "c": "Tipo sanguíneo A.", "d": "Auscência de vesícula.", "e": "Falta de alimentação."}, "answer": "b", "rationale": "O nervo radial circula o úmero; a pressão mantida causa neuropraxia, resultando em ''mão caída''.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Lesão de nervo periférico por posicionamento.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Posicionamento Cirúrgico", "Pós-operatório", "Nervo Radial", "Lesão"]}', 340, 'draft')
